#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Google Calendar OAuth for Roost. Run from the repo root.
# ──────────────────────────────────────────────────────────────────────────

PROJECT="roost-family"
SUPABASE_REF="njhwxoybuxwwtdvebdou"
LOCAL_REDIRECT="http://localhost:55321/functions/v1/calendar-oauth-callback"
PROD_REDIRECT="https://${SUPABASE_REF}.supabase.co/functions/v1/calendar-oauth-callback"
ENV_FILE="supabase/functions/.env"

TOTAL_STAGES=7

banner "Google Calendar for Roost"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Who can use the app"
say "Google needs to know who may sign in. Roost is for families outside your"
say "organisation, so the audience is External; while the app is unverified,"
say "only accounts you list as testers can connect."
open_url "https://console.cloud.google.com/auth/audience?project=${PROJECT}"
step "If the page offers 'Get started', fill in an app name (Roost Family) and"
step "  pick your own address for both the support and developer contact."
step "Set User type / Audience to 'External'."
step "Under 'Test users', click 'Add users' and add the Google account whose"
step "  calendar you'll connect first. Add every adult who will test."
warn "Testing-mode refresh tokens expire after 7 days. That is normal until the app is verified."
pause "Audience set to External, with yourself added as a test user?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "What the app may do"
say "Two scopes: one to read and write events, one to list which calendars the"
say "account has. Roost asks for nothing else."
open_url "https://console.cloud.google.com/auth/scopes?project=${PROJECT}"
step "Click 'Add or remove scopes'."
step "Paste these into the 'Manually add scopes' box, one per line, then 'Add to table':"
say "    https://www.googleapis.com/auth/calendar.events"
say "    https://www.googleapis.com/auth/calendar.calendarlist.readonly"
step "Tick 'openid' and '.../auth/userinfo.email' in the list above if they are not already on."
step "Click 'Update', then 'Save'."
note "calendar.events is a sensitive scope: Google reviews it before the app leaves testing."
pause "Both calendar scopes showing in the table?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the OAuth client"
say "This is the client id and secret Roost's Edge Functions use."
open_url "https://console.cloud.google.com/auth/clients?project=${PROJECT}"
step "Click 'Create client'. Application type: 'Web application'. Name it 'Roost Family'."
step "Under 'Authorised redirect URIs', click 'Add URI' twice and paste both of these:"
say "    ${PROD_REDIRECT}"
say "    ${LOCAL_REDIRECT}"
warn "They must match exactly, including https vs http and no trailing slash."
step "Click 'Create'. Google shows the client id and secret once; copy them now."
ask GOOGLE_CLIENT_ID "Paste the client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the client secret:"
if [[ -z "$GOOGLE_CLIENT_ID" || -z "$GOOGLE_CLIENT_SECRET" ]]; then
  warn "Both values are needed; re-run the wizard once you have them."
  exit 1
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Save them for the local stack"
say "Written to ${ENV_FILE}, which git ignores. The local redirect override is"
say "needed because inside the Docker runtime SUPABASE_URL is not the URL your"
say "browser uses."
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
write_env CALENDAR_OAUTH_REDIRECT_URI "$LOCAL_REDIRECT"
note "Restart 'supabase functions serve' to pick these up."
pause "Saved. Continue?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Save them for production"
say "Edge Function secrets on the hosted project ${SUPABASE_REF}."
if confirm "Set GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET on production now?"; then
  if supabase secrets set --project-ref "$SUPABASE_REF" \
       "GOOGLE_CLIENT_ID=$GOOGLE_CLIENT_ID" "GOOGLE_CLIENT_SECRET=$GOOGLE_CLIENT_SECRET" >/dev/null 2>&1; then
    printf '  %s✓ set%s production secrets\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("production secrets (supabase secrets set --project-ref $SUPABASE_REF GOOGLE_CLIENT_ID=… GOOGLE_CLIENT_SECRET=…)")
    warn "could not set them: is the CLI linked and logged in?"
  fi
else
  SKIPPED+=("production secrets (chose to skip)")
fi
say "Production also needs APP_URL and CALENDAR_FINGERPRINT_KEY. Checking what is there:"
supabase secrets list --project-ref "$SUPABASE_REF" 2>/dev/null | grep -iE "NAME|APP_URL|FINGERPRINT|GOOGLE" || note "could not list secrets"
pause "Continue?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Try it"
say "Connecting happens in a browser, not on the tablet: the consent round trip"
say "needs a session the tablet does not keep."
step "Make sure the local stack is up: supabase start, then supabase functions serve."
step "Run the app: pnpm dev"
open_url "http://localhost:5173/manage"
step "Sign in with your email code, open Calendars, and click 'Connect Google'."
step "Approve the consent screen. Google will warn that the app is unverified: that is expected"
step "  while testing. Choose 'Continue' as the test user you added in stage 1."
step "You land back on /manage, which finishes the connection."
warn "If it says 'not set up yet', the functions server has not picked up the new .env: restart it."
pause "Did the calendar connect?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Afterwards"
say "Two things that catch people out:"
step "Reconnect any calendar connected before today. Older connections hold a"
step "  read-only grant, so 'Add event' stays unavailable until they are reconnected."
step "Verification: while the app is in testing, only the accounts you listed can"
step "  connect, and their access expires weekly. Submit for verification before"
step "  anyone outside that list uses Roost."
open_url "https://console.cloud.google.com/auth/verification?project=${PROJECT}"
note "Verification needs a privacy policy URL, a demo video, and takes days to weeks."
pause "Done?"

finish
